UPDATE proposal_templates SET blocks = jsonb_set(blocks, '{3,html}', to_jsonb($SLIDE$<div style="box-sizing:border-box;width:760px;max-width:760px;min-height:500px;margin:0 auto;padding:32px 36px;border-radius:18px;overflow:hidden;border:1px solid #22c55e;box-shadow:0 0 0 1px rgba(34,197,94,.08),0 8px 24px -12px rgba(34,197,94,.25);font-family:Inter,system-ui,sans-serif;background:linear-gradient(180deg,#ffffff 0%,#f0fdf4 100%);color:#0f172a;display:flex;flex-direction:column;gap:16px;">
  <div style="display:grid;grid-template-columns:1.05fr 1fr;gap:20px;">
    <div>
      <div style="display:inline-flex;align-items:center;gap:6px;background:#16a34a;color:#fff;padding:5px 12px;border-radius:999px;font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;margin-bottom:10px;"><span style="width:5px;height:5px;border-radius:50%;background:#fff;opacity:.9;"></span>Impacto Operacional e Estratégico</div>
      <h2 style="font-size:22px;margin:0 0 10px;font-weight:800;color:#064e3b;letter-spacing:-.02em;line-height:1.15;text-transform:uppercase;">Mais controle, previsibilidade e eficiência para sua operação de <span style="color:#16a34a;">vendas públicas.</span></h2>
      <div style="height:2px;width:46px;background:#22c55e;border-radius:2px;margin-bottom:10px;"></div>
      <p style="margin:0 0 8px;font-size:11.5px;line-height:1.5;color:#334155;">Ao estruturar informações, processos e acompanhamento operacional em uma única plataforma, empresas passam a operar com mais organização, capacidade de acompanhamento e melhor aproveitamento das oportunidades disponíveis no mercado público.</p>
      <p style="margin:0;font-size:11.5px;line-height:1.5;color:#334155;">O <span style="color:#16a34a;font-weight:700;">i-Ganhei</span> contribui para uma operação mais preparada para crescimento, tomada de decisão estratégica e evolução contínua da gestão comercial.</p>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;align-content:start;">
      <div style="display:flex;gap:12px;align-items:flex-start;padding:12px;background:#ffffff;border:2px solid #bbf7d0;border-radius:14px;box-shadow:0 4px 12px -4px #22c55e22;"><div style="width:44px;height:44px;border-radius:50%;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M7 14l4-4 4 4 5-6"/><path d="M16 8h4v4"/></svg></div><div style="min-width:0;"><div style="font-size:12.5px;font-weight:800;color:#064e3b;line-height:1.2;">Mais produtividade operacional</div><div style="height:2px;width:28px;background:#22c55e;margin:6px 0;border-radius:2px;"></div><div style="font-size:11px;color:#475569;line-height:1.35;">Redução de atividades manuais e retrabalho.</div></div></div>
      <div style="display:flex;gap:12px;align-items:flex-start;padding:12px;background:#ffffff;border:2px solid #bbf7d0;border-radius:14px;box-shadow:0 4px 12px -4px #22c55e22;"><div style="width:44px;height:44px;border-radius:50%;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg></div><div style="min-width:0;"><div style="font-size:12.5px;font-weight:800;color:#064e3b;line-height:1.2;">Mais previsibilidade</div><div style="height:2px;width:28px;background:#22c55e;margin:6px 0;border-radius:2px;"></div><div style="font-size:11px;color:#475569;line-height:1.35;">Maior visibilidade sobre oportunidades e evolução da operação.</div></div></div>
      <div style="display:flex;gap:12px;align-items:flex-start;padding:12px;background:#ffffff;border:2px solid #bbf7d0;border-radius:14px;box-shadow:0 4px 12px -4px #22c55e22;"><div style="width:44px;height:44px;border-radius:50%;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a4 4 0 0 0-4 4v1a3 3 0 0 0-2 5 3 3 0 0 0 2 5v1a4 4 0 0 0 8 0v-1a3 3 0 0 0 2-5 3 3 0 0 0-2-5V7a4 4 0 0 0-4-4z"/><path d="M12 8v8M9 11h6"/></svg></div><div style="min-width:0;"><div style="font-size:12.5px;font-weight:800;color:#064e3b;line-height:1.2;">Mais inteligência comercial</div><div style="height:2px;width:28px;background:#22c55e;margin:6px 0;border-radius:2px;"></div><div style="font-size:11px;color:#475569;line-height:1.35;">Decisões apoiadas em informações estruturadas e indicadores.</div></div></div>
      <div style="display:flex;gap:12px;align-items:flex-start;padding:12px;background:#ffffff;border:2px solid #bbf7d0;border-radius:14px;box-shadow:0 4px 12px -4px #22c55e22;"><div style="width:44px;height:44px;border-radius:50%;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2.2"/><path d="M3 20c0-3 3-5 6-5s6 2 6 5"/><path d="M15 20c0-2 2-3.5 4-3.5s2.5 1 2.5 3"/></svg></div><div style="min-width:0;"><div style="font-size:12.5px;font-weight:800;color:#064e3b;line-height:1.2;">Maior capacidade operacional</div><div style="height:2px;width:28px;background:#22c55e;margin:6px 0;border-radius:2px;"></div><div style="font-size:11px;color:#475569;line-height:1.35;">Operação mais organizada, escalável e eficiente.</div></div></div>
