      <div style="width:32px;height:32px;border-radius:50%;border:2px solid #22c55e;background:#f0fdf4;display:flex;align-items:center;justify-content:center;"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 21V5a2 2 0 0 1 2-2h7l5 5v13"/><path d="M14 3v5h5"/></svg></div>
